import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Evaluation and Results","description":"Entry point to the standalone evaluation stack, native 30-case results, reproduction steps, and boundaries that scores must not hide.","frontmatter":{"title":"Evaluation and Results","description":"Entry point to the standalone evaluation stack, native 30-case results, reproduction steps, and boundaries that scores must not hide.","outline":[2,3]},"headers":[],"relativePath":"en/evaluation/index.md","filePath":"en/evaluation/index.md","lastUpdated":1794450028000}'),n={name:"en/evaluation/index.md"};function o(r,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="evaluation-and-results" tabindex="-1">Evaluation and Results <a class="header-anchor" href="#evaluation-and-results" aria-label="Permalink to &quot;Evaluation and Results&quot;">​</a></h1><p class="lead">Evaluation answers a specific question: for the same real tasks, across executors, repetitions, and run modes, what changed in pass rate, quality, duration, tokens, and approvals? It is not a demo that proves capability.</p><h2 id="where-the-evaluation-stack-lives" tabindex="-1">Where the evaluation stack lives <a class="header-anchor" href="#where-the-evaluation-stack-lives" aria-label="Permalink to &quot;Where the evaluation stack lives&quot;">​</a></h2><p>The evaluation code is maintained in the standalone <a href="https://github.com/hearthproject/hearth-eval" target="_blank" rel="noreferrer">hearthproject/hearth-eval</a> repository:</p><ul><li><code>apps/eval-server</code>: experiment orchestration, SQLite, scoring, review, comparison, and SPA hosting;</li><li><code>apps/eval-web</code>: overview, task catalog, experiments, run detail, reviews, comparison, activity, and system status;</li><li><code>packages/eval-core</code>: case contracts, catalog loading, graders, scoring, and scenario statistics;</li><li><code>eval/cases</code>: 60 cases with inputs and golden files;</li><li><code>scenario-runner</code>: 30 white-box integration scenarios that read the sibling Hearth source.</li></ul><p>The main repository keeps only a minimal bridge: <code>POST /api/eval/tasks</code>, <code>POST /api/eval/judge</code>, <code>HEARTH_EVAL_INPUT_ROOT</code>, and <code>.hearth/eval-artifacts/</code>. The evaluation service does not create a second Agent execution path and does not bypass approvals, sandboxing, or permissions.</p><h2 id="native-30-case-results" tabindex="-1">Native 30-case results <a class="header-anchor" href="#native-30-case-results" aria-label="Permalink to &quot;Native 30-case results&quot;">​</a></h2><p>From 2026-11-11 to 11-12, 30 offline cases (evenly sampled from eight task families) ran with the <code>native</code> executor only, one repetition, auto-scoring and auto-retry enabled, and concurrency 4:</p><table tabindex="0"><thead><tr><th>Metric</th><th style="text-align:right;">Result</th></tr></thead><tbody><tr><td>Best complete run</td><td style="text-align:right;"><strong>18/30 passed (60%)</strong>, average score 88.89</td></tr><tr><td>Cumulative targeted confirmation</td><td style="text-align:right;"><strong>19/30</strong> cases reached 100 at least once</td></tr><tr><td>Most recent complete run</td><td style="text-align:right;">12/30 passed (40%), average score 73.33</td></tr><tr><td>Final fix commit</td><td style="text-align:right;"><code>eb32ad5</code>, not yet retested in one uninterrupted 30-case run</td></tr></tbody></table><p>The best run is <code>EXP-20261111145332-7a95ea</code>; the most recent complete run is <code>EXP-20261112003215-b1172b</code>. The cumulative 19/30 comes from different runs and targeted retries, not one continuous experiment, so it is not an official single-run result.</p><p>The most recent complete run was affected by slow provider responses, truncated scoring JSON, and task timeouts, and it predates the final four normalization fixes. Its 40% cannot be treated as the final code capability. Cases such as CAL01 and WEB01 still have semantic ambiguity between input and rubric; T02, T11, and WEB03 reached 100 but were marked <code>sampled</code> and were not counted as formal passes.</p><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h2><ul><li><a href="/hearth-os/evaluation/native-30-final-report-2026-11-12.html">Native 30-task final evaluation report (2026-11-12)</a> — configuration, complete-run summary, per-task results, fixes, risks, and retest guidance. The report is in Chinese.</li><li><a href="/hearth-os/evaluation/native-30-baseline-2026-11-11.html">Native 30-task baseline evaluation (2026-11-11)</a> — the invalid 0/30 baseline caused by a missing tool allowlist, and how the bridge failure was isolated. The report is in Chinese.</li></ul><h2 id="reproducing" tabindex="-1">Reproducing <a class="header-anchor" href="#reproducing" aria-label="Permalink to &quot;Reproducing&quot;">​</a></h2><p>The main service must allow the evaluation service to read case inputs:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># hearth-os\\.env</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HEARTH_EVAL_INPUT_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D:\\App\\hearth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">eval\\eval</span></span></code></pre></div><p>The evaluation service must set the artifact root explicitly; otherwise it cannot find registered artifacts and incorrectly reports <code>BLOCKER_FAILED: exists</code>:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HEARTH_EVAL_ARTIFACT_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;D:\\App\\hearth-os\\.hearth\\eval-artifacts&#39;</span></span></code></pre></div><p>Then open the console at <code>http://127.0.0.1:5174</code>, select 30 offline cases, the <code>native</code> executor, one repetition, offline mode, auto-scoring, and auto-retry, and start the experiment. After a restart, confirm <code>artifactRoot</code> through <code>GET /api/system</code> before starting another experiment.</p><h2 id="what-a-score-does-not-prove" tabindex="-1">What a score does not prove <a class="header-anchor" href="#what-a-score-does-not-prove" aria-label="Permalink to &quot;What a score does not prove&quot;">​</a></h2><ul><li>Automated tests and scenario passes prove the control plane, scoring logic, and failure boundaries, not real pass rates.</li><li>Offline cases do not cover real mail accounts, real calendars, real desktop devices, or <code>live-only</code> tasks.</li><li>Unavailable judges, judge conflicts, and sampled reviews enter <code>needs_review</code>; they are never silently counted as passes.</li><li>Commit <code>eb32ad5</code> still lacks one uninterrupted 30-case run. Every single-run number must be reported with its experiment ID, commit, and run conditions.</li></ul>`,21)])])}const v=a(n,[["render",o]]);export{u as __pageData,v as default};
